function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = '#000000';

  // draw mirror
  ctx.fillStyle = '#AAAAAA';
  ctx.fillRect(W/2 - 50, H/2 - 100, 100, 200);
  ctx.strokeRect(W/2 - 50, H/2 - 100, 100, 200);

  // draw reflection
  ctx.fillStyle = '#000000';
  ctx.beginPath();
  ctx.arc(W/2 - 20 + 30 * Math.sin(t), H/2 - 20, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20 + 30 * Math.sin(t), H/2 + 20);
  ctx.lineTo(W/2 - 20 + 30 * Math.sin(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20 + 30 * Math.sin(t), H/2 + 20);
  ctx.lineTo(W/2 - 50 + 30 * Math.sin(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20 + 30 * Math.sin(t), H/2 + 20);
  ctx.lineTo(W/2 + 10 + 30 * Math.sin(t), H/2 + 50);
  ctx.stroke();

  // draw truth self
  ctx.fillStyle = '#000000';
  ctx.beginPath();
  ctx.arc(W/2 + 80, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 80, H/2 + 20);
  ctx.lineTo(W/2 + 80, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 80, H/2 + 20);
  ctx.lineTo(W/2 + 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 80, H/2 + 20);
  ctx.lineTo(W/2 + 110, H/2 + 50);
  ctx.stroke();

  ctx.restore();
}
